//! The proof that the library's 004-family helpers equal the scripts' own
//! Python: `data/family004_corpus.txt`, generated by
//! `tools/gen_family004_corpus.py` (which runs each script's own definitions
//! and inline rules with Python 3.10 and 3.13), recomputed here with the
//! library, result by result.
//!
//! Each result is the canonical JSON of the function's value (as Python's
//! `json.dumps(…, ensure_ascii=False, separators=(",", ":"))` writes it),
//! hashed with FNV-1a 64; the corpus keeps the low 32 bits. On a mismatch the
//! test prints the input and the library's JSON, so the Python side can be
//! rerun on the same input.

use super::blocks::{FormRows, block_role, form_rows, is_placeholder, section_blocks};
use super::evidence::{
    LinePolicy, TableTagRule, TagPolicy, has_tag, subsections_untagged,
    subsections_with_table_untagged, untagged, untagged_lines, untagged_tables,
};
use super::family004::{
    NameNorm, SpanRule, WidthRule, bit_positions, heading_index, norm_name, parse_int_token,
    section_span, subsections, tables, width_to_bits,
};
use super::items::{OpenItemPolicy, item_is_owned, open_items};
use super::negation::{Lookback, negated};
use super::pycompat::splitlines;
use super::sentences::{
    RAW_COLON, RAW_COLON_NEWLINES_004_19, RAW_NEWLINE_004_11, RAW_PERIOD_SEMI, RAW_PIPE_004_21,
    RAW_TERMINAL_004_03, SentenceSplit, first_sentence_004_29, split, split_raw,
};
use super::text::{join_digit_groups, rx};
use super::units::{BlockKind, clean_start, prose_blocks, strip_fences};

const CORPUS: &str = include_str!("../../data/family004_corpus.txt");

/// A JSON value as the corpus writes it.
#[derive(Debug, Clone, PartialEq)]
enum J {
    N,
    B(bool),
    I(i128),
    S(String),
    L(Vec<J>),
}

impl J {
    fn dump(&self, out: &mut String) {
        match self {
            J::N => out.push_str("null"),
            J::B(b) => out.push_str(if *b { "true" } else { "false" }),
            J::I(i) => out.push_str(&i.to_string()),
            J::S(s) => {
                out.push('"');
                for c in s.chars() {
                    match c {
                        '"' => out.push_str("\\\""),
                        '\\' => out.push_str("\\\\"),
                        '\n' => out.push_str("\\n"),
                        '\r' => out.push_str("\\r"),
                        '\t' => out.push_str("\\t"),
                        '\u{8}' => out.push_str("\\b"),
                        '\u{c}' => out.push_str("\\f"),
                        c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
                        c => out.push(c),
                    }
                }
                out.push('"');
            }
            J::L(v) => {
                out.push('[');
                for (k, x) in v.iter().enumerate() {
                    if k > 0 {
                        out.push(',');
                    }
                    x.dump(out);
                }
                out.push(']');
            }
        }
    }

    fn text(&self) -> String {
        let mut s = String::new();
        self.dump(&mut s);
        s
    }

    fn as_str(&self) -> &str {
        match self {
            J::S(s) => s,
            _ => panic!("not a string: {self:?}"),
        }
    }
}

/// A minimal JSON reader for the corpus (strings, ints, lists).
fn parse(s: &str) -> (J, &str) {
    let s = s.trim_start();
    match s.as_bytes().first() {
        Some(b'"') => {
            let mut out = String::new();
            let mut it = s[1..].char_indices();
            while let Some((i, c)) = it.next() {
                match c {
                    '"' => return (J::S(out), &s[1 + i + 1..]),
                    '\\' => match it.next().map(|x| x.1) {
                        Some('n') => out.push('\n'),
                        Some('t') => out.push('\t'),
                        Some('r') => out.push('\r'),
                        Some('b') => out.push('\u{8}'),
                        Some('f') => out.push('\u{c}'),
                        Some('u') => {
                            let hex: String =
                                (0..4).filter_map(|_| it.next().map(|x| x.1)).collect();
                            let v = u32::from_str_radix(&hex, 16).expect("hex");
                            out.push(char::from_u32(v).expect("scalar"));
                        }
                        Some(o) => out.push(o),
                        None => break,
                    },
                    c => out.push(c),
                }
            }
            panic!("unterminated string")
        }
        Some(b'[') => {
            let mut v = Vec::new();
            let mut rest = s[1..].trim_start();
            if let Some(r) = rest.strip_prefix(']') {
                return (J::L(v), r);
            }
            loop {
                let (x, r) = parse(rest);
                v.push(x);
                let r = r.trim_start();
                if let Some(r) = r.strip_prefix(',') {
                    rest = r;
                } else {
                    return (J::L(v), r.trim_start().strip_prefix(']').expect("]"));
                }
            }
        }
        _ if s.starts_with("null") => (J::N, &s[4..]),
        _ if s.starts_with("true") => (J::B(true), &s[4..]),
        _ if s.starts_with("false") => (J::B(false), &s[5..]),
        _ => {
            let end = s
                .find(|c: char| !(c.is_ascii_digit() || c == '-'))
                .unwrap_or(s.len());
            (
                J::I(super::pycompat::parse_int(&s[..end]).expect("int")),
                &s[end..],
            )
        }
    }
}

fn fnv32(text: &str) -> String {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for b in text.bytes() {
        h ^= u64::from(b);
        h = h.wrapping_mul(0x0100_0000_01b3);
    }
    format!("{:08x}", h & 0xffff_ffff)
}

fn s(x: &str) -> J {
    J::S(x.to_string())
}

fn strs<S: AsRef<str>>(v: &[S]) -> J {
    J::L(v.iter().map(|x| s(x.as_ref())).collect())
}

fn int(n: usize) -> J {
    J::I(i128::try_from(n).expect("small"))
}

fn opt_span(x: Option<(usize, usize)>) -> J {
    x.map_or(J::N, |(a, b)| J::L(vec![int(a), int(b)]))
}

fn lvl(l: Option<usize>) -> J {
    l.map_or(J::N, int)
}

const PATTERNS: [&str; 8] = [
    "probe",
    "^Hello$",
    "reply",
    "section types?",
    "Open items",
    "nothing-matches",
    "Rejection",
    "^Path-MTU",
];

fn per_line(t: &str, f: impl Fn(&str) -> String) -> J {
    J::L(splitlines(t).into_iter().map(|l| J::S(f(l))).collect())
}

fn table_cells(t: &str) -> Vec<String> {
    let mut out = Vec::new();
    for tb in tables(t) {
        out.extend(tb.head().iter().cloned());
        for r in &tb.rows {
            out.extend(r.cells.iter().cloned());
        }
    }
    out
}

fn widths(t: &str, rule: WidthRule) -> J {
    J::L(
        table_cells(t)
            .iter()
            .map(|c| match width_to_bits(c, rule) {
                Ok(Some(n)) => J::I(n),
                Ok(None) => J::N,
                Err(e) => s(&format!("OVERFLOW {e}")),
            })
            .collect(),
    )
}

fn sentences(t: &str, how: SentenceSplit) -> J {
    strs(&split(t, how))
}

fn items(t: &str, rule: OpenItemPolicy) -> J {
    J::L(
        open_items(t, rule)
            .iter()
            .map(|i| J::L(vec![s(&i.text), J::B(item_is_owned(i, rule))]))
            .collect(),
    )
}

fn untagged_texts(t: &str, p: &TagPolicy) -> J {
    J::L(untagged(t, p).into_iter().map(|u| J::S(u.text)).collect())
}

fn kinds_with(t: &str, p: &TagPolicy, tables_rule: TableTagRule) -> J {
    // the rules interleave prose and table failures in text order
    let mut all: Vec<(usize, &str, String)> = untagged(t, p)
        .into_iter()
        .map(|u| (u.line, "prose", u.text))
        .chain(
            untagged_tables(t, tables_rule)
                .into_iter()
                .map(|u| (u.line, "table", u.text)),
        )
        .collect();
    all.sort_by_key(|x| x.0);
    J::L(
        all.into_iter()
            .map(|(_, k, x)| J::L(vec![s(k), J::S(x)]))
            .collect(),
    )
}

fn lookback_24(t: &str) -> J {
    let mut out = Vec::new();
    for line in splitlines(t) {
        // `\b[A-Za-z]+\b`: the Python words made of ASCII letters only
        let mut at = 0;
        for (i, c) in line.char_indices().chain([(line.len(), ' ')]) {
            if super::pycompat::is_word(c) && i < line.len() {
                continue;
            }
            let w = &line[at..i];
            if !w.is_empty() && w.chars().all(|c| c.is_ascii_alphabetic()) {
                out.push(J::L(vec![
                    int(line[..at].chars().count()),
                    J::B(negated(line, at, w, &Lookback::WINDOW_24_004_16)),
                ]));
            }
            at = i + c.len_utf8();
        }
    }
    J::L(out)
}

fn named(t: &str, pattern: &str, rule: &Lookback) -> J {
    let mut out = Vec::new();
    for line in splitlines(t) {
        for m in rx(pattern).find_iter(line) {
            out.push(J::L(vec![
                s(m.as_str()),
                J::B(negated(line, m.start(), m.as_str(), rule)),
            ]));
        }
    }
    J::L(out)
}

fn spans(t: &str, levels: &[Option<usize>], rule: SpanRule, with_level: bool) -> J {
    let lines = splitlines(t);
    let heads = heading_index(&lines);
    let mut out = Vec::new();
    for p in PATTERNS {
        for &l in levels {
            let span = opt_span(section_span(lines.len(), &heads, p, l, rule));
            out.push(J::L(if with_level {
                vec![s(p), lvl(l), span]
            } else {
                vec![s(p), span]
            }));
        }
    }
    J::L(out)
}

/// The library's value for (helper, variant) on `t`.
fn library(helper: &str, variant: &str, t: &str) -> J {
    let lines = splitlines(t);
    match (helper, variant) {
        ("heading_index", _) => J::L(
            heading_index(&lines)
                .into_iter()
                .map(|(i, l, title)| J::L(vec![int(i), int(l), J::S(title)]))
                .collect(),
        ),
        ("parse_tables", _) => J::L(
            tables(t)
                .iter()
                .map(|tb| {
                    J::L(vec![
                        int(tb.line),
                        strs(tb.head()),
                        J::L(tb.rows.iter().map(|r| strs(&r.cells)).collect()),
                    ])
                })
                .collect(),
        ),
        ("strip_fences", _) => J::S(strip_fences(t)),
        ("blocks", _) => strs(&super::blocks::blank_blocks(t)),
        ("prose_blocks", _) => J::L(
            prose_blocks(t)
                .into_iter()
                .map(|b| {
                    J::L(vec![
                        s(if b.kind == BlockKind::Table { "t" } else { "p" }),
                        J::S(b.text),
                    ])
                })
                .collect(),
        ),
        ("clean_start", _) => per_line(t, clean_start),
        ("subsections", _) => J::L(
            subsections(&lines.join("\n"))
                .into_iter()
                .map(|(a, b)| J::L(vec![J::S(a), J::S(b)]))
                .collect(),
        ),
        ("section_span", "004-16") => spans(
            t,
            &[None, Some(2), Some(3)],
            SpanRule::AfterHeading004_16,
            true,
        ),
        ("section_span", "004-19") => spans(t, &[None], SpanRule::AfterHeading004_16, false),
        ("span_of", _) => spans(t, &[Some(2), Some(3)], SpanRule::WithHeading004_24, true),
        ("norm_name", "004-06") => per_line(t, |l| norm_name(l, NameNorm::Alnum004_06)),
        ("norm_name", "004-16") => per_line(t, |l| norm_name(l, NameNorm::Spaced004_16)),
        ("norm", "004-20") => per_line(t, |l| norm_name(l, NameNorm::Letters004_20)),
        ("norm", "004-24") => per_line(t, join_digit_groups),
        ("width_to_bits", "004-06") => widths(t, WidthRule::DigitGroups004_06),
        ("width_to_bits", "004-20") => widths(t, WidthRule::FirstNumber004_20),
        ("parse_int_token", _) => J::L(
            lines
                .iter()
                .map(|l| match parse_int_token(l) {
                    Ok(Some(n)) => J::I(n),
                    Ok(None) => J::N,
                    Err(e) => s(&format!("OVERFLOW {e}")),
                })
                .collect(),
        ),
        ("bit_positions", _) => J::L(
            lines
                .iter()
                .map(|l| bit_positions(l).map_or(J::N, |(a, b)| J::L(vec![J::I(a), J::I(b)])))
                .collect(),
        ),
        ("sentences", "004-20") => sentences(t, SentenceSplit::NEWLINES_004_20),
        ("sentences", "004-25") => sentences(t, SentenceSplit::BLOCKS_004_25),
        ("sentences_of", "004-29") => sentences(t, SentenceSplit::PARAGRAPHS_004_29),
        ("sents", "004-12") => sentences(t, SentenceSplit::LINES_004_12),
        ("split_sentences", "004-04") => J::L(
            lines
                .iter()
                .map(|l| strs(&split(l, SentenceSplit::TERMINAL_004_04)))
                .collect(),
        ),
        ("prose_sentences", "004-09") => J::L(
            super::blocks::blank_blocks(&strip_fences(t))
                .iter()
                .filter(|b| {
                    !b.trim_start_matches(super::pycompat::is_space)
                        .starts_with('|')
                })
                .flat_map(|b| split(b, SentenceSplit::PERIOD_SEMI))
                .map(J::S)
                .collect(),
        ),
        ("SENT", "004-24") => sentences(t, SentenceSplit::COLON_004_24),
        ("split_raw", _) => strs(&split_raw(t, RAW_PERIOD_SEMI)),
        ("split_raw_colon", _) => strs(&split_raw(t, RAW_COLON)),
        ("split_raw_colon_newlines", _) => strs(&split_raw(t, RAW_COLON_NEWLINES_004_19)),
        ("split_raw_newline", _) => strs(&split_raw(t, RAW_NEWLINE_004_11)),
        ("split_raw_pipe", _) => strs(&split_raw(t, RAW_PIPE_004_21)),
        ("split_raw_terminal", _) => strs(&split_raw(t, RAW_TERMINAL_004_03)),
        ("first_sentence", _) => per_line(t, |l| first_sentence_004_29(l).to_string()),
        _ => rules(helper, variant, t, &lines),
    }
}

/// The library's value for the rule helpers (form rows, blocks, tags, open
/// items, look-backs).
fn rules(helper: &str, variant: &str, t: &str, lines: &[&str]) -> J {
    match (helper, variant) {
        ("form_rows", "004-17") => J::L(
            form_rows(t, FormRows::AnyCell004_17)
                .iter()
                .map(|r| strs(r))
                .collect(),
        ),
        ("Sec.form_rows", "004-20") => J::L(
            form_rows(t, FormRows::FirstCell004_20)
                .iter()
                .map(|r| strs(r))
                .collect(),
        ),
        ("section_blocks", _) => J::L(
            section_blocks(lines)
                .iter()
                .map(|b| J::L(vec![s(block_role(b).name()), strs(b)]))
                .collect(),
        ),
        ("is_placeholder", _) | ("placeholder", _) => J::B(is_placeholder(Some(t))),
        ("every_block", _) => untagged_texts(t, &TagPolicy::EVERY_BLOCK_004_03),
        ("lines_untagged", _) => strs(&untagged_lines(t, &LinePolicy::LINES_004_24)),
        ("prose_split", _) => untagged_texts(t, &TagPolicy::PROSE_004_29),
        ("prose_nonspace", _) => untagged_texts(t, &TagPolicy::PROSE_004_26),
        ("prose_alpha", _) => kinds_with(
            t,
            &TagPolicy::ALPHA_004_16,
            TableTagRule::SectionTagged004_16,
        ),
        ("blocks_alpha", _) => {
            kinds_with(t, &TagPolicy::BLOCKS_004_19, TableTagRule::AfterProse004_19)
        }
        ("subs_with_table", _) => strs(&subsections_with_table_untagged(&lines.join("\n"))),
        ("subs_any", _) => strs(&subsections_untagged(&subsections(&lines.join("\n")))),
        ("open_mention_blocks", _) => items(t, OpenItemPolicy::MentionBlocks),
        ("open_leading", _) => items(t, OpenItemPolicy::Leading),
        ("open_head40", _) => items(t, OpenItemPolicy::Head40),
        ("open_clean", _) => items(t, OpenItemPolicy::LeadingClean),
        ("open_window3", _) => items(t, OpenItemPolicy::Window3),
        ("open_wleading", _) => items(t, OpenItemPolicy::WordLeading),
        ("lookback_24", _) => lookback_24(t),
        ("lookback_25", _) => named(
            t,
            r"\b[A-Z][a-z]+(?:[A-Z][a-z]+)+\b",
            &Lookback::WINDOW_25_004_19,
        ),
        ("preceding", _) => named(
            t,
            r"\b[A-Z][a-z]+(?:[A-Z][a-z]+)+\b",
            &Lookback::ANYWHERE_004_16,
        ),
        _ => panic!("no library function for {helper} {variant}"),
    }
}

/// The corpus inputs, in order: (id, text).
fn inputs() -> Vec<(String, String)> {
    let mut out: Vec<(String, String)> = Vec::new();
    for line in CORPUS.lines().filter(|l| l.starts_with("input ")) {
        let mut f = line.splitn(4, ' ');
        let (_, id, kind, rest) = (
            f.next(),
            f.next().expect("id"),
            f.next().expect("kind"),
            f.next().unwrap_or(""),
        );
        let text = match kind {
            "excerpt" => {
                let (_, r) = parse(rest);
                parse(r).0.as_str().to_string()
            }
            "synthetic" => parse(rest).0.as_str().to_string(),
            "mutation" => {
                let (_, op) = rest.split_once(' ').expect("base op");
                let prev = &out.last().expect("a base before its mutations").1;
                let mut lines: Vec<String> = prev.split('\n').map(String::from).collect();
                let J::L(op) = parse(op).0 else { panic!("op") };
                let k = match &op[1] {
                    J::I(k) => usize::try_from(*k).expect("index"),
                    other => panic!("index {other:?}"),
                };
                match op[0].as_str() {
                    "ins" => lines.insert(k, op[2].as_str().to_string()),
                    "del" => {
                        lines.remove(k);
                    }
                    _ => lines[k] = op[2].as_str().to_string(),
                }
                lines.join("\n")
            }
            other => panic!("input kind {other}"),
        };
        out.push((id.to_string(), text));
    }
    out
}

/// The results of one `result` line that differ: (count checked, failures).
fn check_line(line: &str, inputs: &[(String, String)]) -> (usize, Vec<String>) {
    let f: Vec<&str> = line.split(' ').collect();
    let (helper, variant, hashes) = (f[1], f[2], &f[3..]);
    assert_eq!(hashes.len(), inputs.len(), "{helper} {variant}");
    let mut bad = Vec::new();
    for ((id, text), want) in inputs.iter().zip(hashes) {
        let got = library(helper, variant, text).text();
        if fnv32(&got) != *want {
            bad.push(format!(
                "{helper} {variant} on {id}: library {}",
                &got[..got.len().min(400)]
            ));
        }
    }
    (hashes.len(), bad)
}

#[test]
fn the_library_equals_the_scripts_on_the_family004_corpus() {
    let inputs = inputs();
    assert!(inputs.len() > 100, "{} inputs", inputs.len());
    let lines: Vec<&str> = CORPUS
        .lines()
        .filter(|l| l.starts_with("result "))
        .collect();
    // one thread per result line: the corpus is a few thousand evaluations
    let results: Vec<(usize, Vec<String>)> = std::thread::scope(|sc| {
        let handles: Vec<_> = lines
            .iter()
            .map(|l| sc.spawn(|| check_line(l, &inputs)))
            .collect();
        handles
            .into_iter()
            .map(|h| h.join().expect("a proof thread panicked"))
            .collect()
    });
    let checked: usize = results.iter().map(|r| r.0).sum();
    let bad: Vec<String> = results.into_iter().flat_map(|r| r.1).collect();
    assert!(checked > 5000, "{checked} results");
    assert!(
        bad.is_empty(),
        "{} of {checked} results differ:\n{}",
        bad.len(),
        bad[..bad.len().min(40)].join("\n")
    );
}

#[test]
fn the_json_and_hash_match_python() {
    // python3 -c 'import json; print(json.dumps([1,None,True,"a\"\\\né\x01"], ensure_ascii=False, separators=(",",":")))'
    let v = J::L(vec![J::I(1), J::N, J::B(true), s("a\"\\\né\u{1}")]);
    assert_eq!(v.text(), "[1,null,true,\"a\\\"\\\\\\né\\u0001\"]");
    assert_eq!(parse(&v.text()).0, v);
    // FNV-1a 64 of "" is the offset basis
    assert_eq!(fnv32(""), "84222325");
    assert!(has_tag("[code]"));
}
